import { useEffect, useRef } from 'react';

type Theme = 'aurora' | 'sunset' | 'neon';

interface Particle {
  posX: number;
  posY: number;
  velX: number;
  velY: number;
  radius: number;
  twinklePhase: number;
  twinkleSpeed: number;
}

interface Meteor {
  x: number;
  y: number;
  vx: number;
  vy: number;
  life: number;
  maxLife: number;
  size: number;
}

const THEME_COLORS: Record<Theme, { r: number; g: number; b: number }> = {
  aurora: { r: 34, g: 211, b: 238 },
  sunset: { r: 251, g: 146, b: 60 },
  neon: { r: 232, g: 121, b: 249 },
};

export default function ParticleNetwork({ theme }: { theme: Theme }) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const particlesRef = useRef<Particle[]>([]);
  const meteorsRef = useRef<Meteor[]>([]);
  const mouseRef = useRef({ x: -9999, y: -9999 });
  const themeRef = useRef(theme);

  useEffect(() => {
    themeRef.current = theme;
  }, [theme]);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let frameId = 0;
    let lastTime = 0;

    const resize = () => {
      const parent = canvas.parentElement;
      if (!parent) return;
      const dpr = window.devicePixelRatio || 1;
      canvas.width = parent.clientWidth * dpr;
      canvas.height = parent.clientHeight * dpr;
      canvas.style.width = parent.clientWidth + 'px';
      canvas.style.height = parent.clientHeight + 'px';
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      initParticles(parent.clientWidth, parent.clientHeight);
    };

    const initParticles = (width: number, height: number) => {
      const count = Math.min(110, Math.floor((width * height) / 11000));
      const list: Particle[] = [];
      for (let i = 0; i < count; i++) {
        list.push({
          posX: Math.random() * width,
          posY: Math.random() * height,
          velX: (Math.random() - 0.5) * 0.6,
          velY: (Math.random() - 0.5) * 0.6,
          radius: Math.random() * 1.8 + 0.8,
          twinklePhase: Math.random() * Math.PI * 2,
          twinkleSpeed: 0.02 + Math.random() * 0.03,
        });
      }
      particlesRef.current = list;
    };

    const spawnMeteor = (width: number, height: number) => {
      const startX = Math.random() * width * 0.8 + width * 0.1;
      const angle = Math.PI * 0.2 + Math.random() * 0.2;
      meteorsRef.current.push({
        x: startX,
        y: -10,
        vx: Math.cos(angle) * 6,
        vy: Math.sin(angle) * 6,
        life: 0,
        maxLife: 40 + Math.random() * 30,
        size: 1.5 + Math.random() * 1.5,
      });
    };

    const handleMove = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      mouseRef.current = { x: e.clientX - rect.left, y: e.clientY - rect.top };
    };
    const handleLeave = () => {
      mouseRef.current = { x: -9999, y: -9999 };
    };

    const draw = (now: number) => {
      const dt = now - lastTime;
      lastTime = now;

      const width = canvas.clientWidth;
      const height = canvas.clientHeight;
      const color = THEME_COLORS[themeRef.current];
      const particles = particlesRef.current;
      const mouse = mouseRef.current;

      ctx.clearRect(0, 0, width, height);

      // 유성 생성 (평균 3초마다)
      if (Math.random() < 0.006) {
        spawnMeteor(width, height);
      }

      // 유성 업데이트 & 렌더링
      const meteors = meteorsRef.current;
      for (let i = meteors.length - 1; i >= 0; i--) {
        const m = meteors[i];
        m.x += m.vx;
        m.y += m.vy;
        m.life++;

        if (m.life > m.maxLife || m.x > width + 50 || m.y > height + 50) {
          meteors.splice(i, 1);
          continue;
        }

        const progress = m.life / m.maxLife;
        const tailLen = 8;
        for (let t = 0; t < tailLen; t++) {
          const ratio = t / tailLen;
          const tx = m.x - m.vx * ratio * 4;
          const ty = m.y - m.vy * ratio * 4;
          const alpha = (1 - ratio) * (1 - progress * 0.5) * 0.9;
          const r = m.size * (1 - ratio * 0.6);
          ctx.beginPath();
          ctx.arc(tx, ty, r, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(255,255,255,${alpha})`;
          ctx.fill();
        }
      }

      // 별 업데이트
      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];
        p.posX += p.velX;
        p.posY += p.velY;
        p.twinklePhase += p.twinkleSpeed;

        if (p.posX < 0 || p.posX > width) p.velX *= -1;
        if (p.posY < 0 || p.posY > height) p.velY *= -1;

        const dxMouse = p.posX - mouse.x;
        const dyMouse = p.posY - mouse.y;
        const distMouse = Math.hypot(dxMouse, dyMouse);
        if (distMouse < 140 && distMouse > 0) {
          const force = (140 - distMouse) / 140;
          p.posX += (dxMouse / distMouse) * force * 2.5;
          p.posY += (dyMouse / distMouse) * force * 2.5;
        }
      }

      // 연결선
      for (let i = 0; i < particles.length; i++) {
        for (let j = i + 1; j < particles.length; j++) {
          const a = particles[i];
          const b = particles[j];
          const dist = Math.hypot(a.posX - b.posX, a.posY - b.posY);
          if (dist < 120) {
            const alpha = (1 - dist / 120) * 0.7;
            ctx.strokeStyle = `rgba(${color.r},${color.g},${color.b},${alpha})`;
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            ctx.moveTo(a.posX, a.posY);
            ctx.lineTo(b.posX, b.posY);
            ctx.stroke();
          }
        }
      }

      // 별 렌더링 (반짝임 적용)
      for (let i = 0; i < particles.length; i++) {
        const p = particles[i];
        const twinkle = 0.5 + 0.5 * Math.sin(p.twinklePhase);
        const drawRadius = p.radius * (0.8 + twinkle * 0.5);
        const opacity = 0.6 + twinkle * 0.4;

        ctx.beginPath();
        ctx.arc(p.posX, p.posY, drawRadius, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${color.r},${color.g},${color.b},${opacity})`;
        ctx.shadowBlur = 10 + twinkle * 12;
        ctx.shadowColor = `rgba(${color.r},${color.g},${color.b},${0.6 + twinkle * 0.4})`;
        ctx.fill();
        ctx.shadowBlur = 0;
      }

      frameId = requestAnimationFrame(draw);
    };

    resize();
    window.addEventListener('resize', resize);
    canvas.addEventListener('mousemove', handleMove);
    canvas.addEventListener('mouseleave', handleLeave);
    frameId = requestAnimationFrame(draw);

    return () => {
      cancelAnimationFrame(frameId);
      window.removeEventListener('resize', resize);
      canvas.removeEventListener('mousemove', handleMove);
      canvas.removeEventListener('mouseleave', handleLeave);
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className="absolute inset-0 w-full h-full"
      style={{
        background:
          'radial-gradient(circle at 50% 40%, rgba(30,41,59,0.6), rgba(2,6,23,1))',
      }}
    />
  );
}
